import{d as l,C as t,o as h,c as m,j as i,a as e,E as a,a3 as u}from"./chunks/framework.Q4yG9rk_.js";const x=JSON.parse('{"title":"中庸·第33章","description":"《中庸》第 33 章——衣锦尚絅，闇然而日章：淡而不厌，简而文，温而理；内省不疚，不愧屋漏；不赏而民劝，笃恭而天下平；上天之载，无声无臭，至矣。","frontmatter":{"title":"中庸·第33章","description":"《中庸》第 33 章——衣锦尚絅，闇然而日章：淡而不厌，简而文，温而理；内省不疚，不愧屋漏；不赏而民劝，笃恭而天下平；上天之载，无声无臭，至矣。","category":"guide","aliases":["第33章","中庸第33章","衣锦尚絅","无声无臭"],"source":["《礼记》","《四书章句集注》"],"outline":[2,3]},"headers":[],"relativePath":"lizhimingde/sishu-wujing/zhongyong/chapter-33.md","filePath":"lizhimingde/sishu-wujing/zhongyong/chapter-33.md","lastUpdated":1790316338000}'),d={name:"lizhimingde/sishu-wujing/zhongyong/chapter-33.md"},b=l({...d,setup(y){const s=[{id:"yijin",label:"衣锦尚絅 · 闇然而日章 · 淡而不厌，简而文，温而理",showLabel:!0,sentences:[["《诗》曰“",{text:"衣锦尚絅",glossary:"yijinshangjiong"},"”，",{text:"恶其文之著",glossary:"wuqiwen"},"也。故君子之道，",{text:"闇然而日章",glossary:"anran"},"；小人之道，",{text:"的然而日亡",glossary:"diran"},"。君子之道：",{text:"淡而不厌",glossary:"danbuyan"},"，",{text:"简而文",glossary:"jianwen"},"，",{text:"温而理",glossary:"wenli"},"，"]],note:"引《诗》「衣锦尚絅」——身穿锦服，外面还要罩一件麻纱单衣（絅＝单罩衣），是「恶其文之著也」——嫌其文采太显露。故「君子之道，闇然而日章；小人之道，的然而日亡」——君子之道暗然而日渐彰明，小人之道昭然而日渐消亡。又：「淡而不厌，简而文，温而理」。"},{id:"rudre",label:"知远之近，知风之自，知微之显 · 可与入德矣",showLabel:!0,sentences:[[{text:"知远之近",glossary:"zhiyuan"},"，",{text:"知风之自",glossary:"zhifeng"},"，",{text:"知微之显",glossary:"zhiwei"},"，可与",{text:"入德",glossary:"rude"},"矣。"]],note:"「知远之近，知风之自，知微之显」——知道远由近始、风有其自、微将显著；能知此三者，「可与入德矣」——就可以进于德了。"},{id:"qianfu",label:"潜虽伏矣，亦孔之昭 · 内省不疚，人之所不见",showLabel:!0,sentences:[["《诗》云：“潜虽伏矣，亦孔之昭！”故君子",{text:"内省不疚",glossary:"neixingbujiu"},"，",{text:"无恶于志",glossary:"wuwuyuzhi"},"。君子之所不可及者，其唯人之所不见乎。"]],note:"引《诗》「潜虽伏矣，亦孔之昭」——虽潜藏伏匿，也极其昭明。故「君子内省不疚，无恶于志」——君子反省而无所愧疚，无愧于心。又「君子之所不可及者，其唯人之所不见乎」——君子之所以不可企及，大概正在别人看不见的地方。"},{id:"wulou",label:"相在尔室，尚不愧于屋漏 · 不动而敬，不言而信",showLabel:!0,sentences:[["《诗》云：“相在尔室，尚不愧于",{text:"屋漏",glossary:"wulou"},"。”故君子不动而敬，不言而信。"]],note:"引《诗》「相在尔室，尚不愧于屋漏」——看你独处室中，尚且不愧于屋漏（屋漏＝室内西北角暗处，代指无人之处）。故「君子不动而敬，不言而信」——君子不必动作而自敬，不必言语而自信。"},{id:"bushang",label:"奏假无言 · 不赏而民劝 · 不显惟德，笃恭而天下平",showLabel:!0,sentences:[["《诗》曰：“奏假无言，时靡有争。”是故君子不赏而民劝，不怒而民威于",{text:"鈇钺",glossary:"fuyue"},"。"],["《诗》曰：“",{text:"不显惟德",glossary:"buxianweide"},"！百辟其",{text:"刑",glossary:"xing"},"之。”是故君子笃恭而天下平。"]],note:"引《诗》「奏假无言，时靡有争」——进献祭乐而无所祷告，此时无人相争。故「君子不赏而民劝，不怒而民威于鈇钺」——不赏而百姓自勉，不怒而百姓比畏刑具更甚。又引「不显惟德！百辟其刑之」——德虽不显而诸侯效法，故「君子笃恭而天下平」。"},{id:"wusheng",label:"不大声以色 · 声色之于以化民，末也 · 无声无臭，至矣",showLabel:!0,sentences:[["《诗》云：“予怀明德，不大声以色。”子曰：“声色之于以化民，末也。”《诗》曰：“",{text:"德輶如毛",glossary:"deyourumao"},"”，毛犹有",{text:"伦",glossary:"lun"},"。“",{text:"上天之载",glossary:"shangtianzhizai"},"，",{text:"无声无臭",glossary:"wushengwuxiu"},"”，至矣！"]],note:"引《诗》「予怀明德，不大声以色」——我怀明德，不靠大声与厉色。孔子遂曰：「声色之于以化民，末也」——用声威颜色来化民，是末节。再引「德輶如毛」（德轻如毛），「毛犹有伦」（毛尚可比拟）；而「上天之载，无声无臭」——上天之事，无声无臭，「至矣」！全篇以此收束，归于「无声无臭」之至境。"}],o=[{id:"yijinshangjiong",term:"衣锦尚絅",pinyin:"yì jǐn shàng jiǒng",meaning:"衣：穿，读 yì；絅：单衣（罩衣）。穿着锦衣，外面再罩一件单衣——《诗·卫风·硕人》句。"},{id:"wuqiwen",term:"恶其文之著",pinyin:"wù qí wén zhī zhù",meaning:"厌恶文采过于显露。恶：读 wù。"},{id:"anran",term:"闇然而日章",pinyin:"àn rán ér rì zhāng",meaning:"闇然：暗然、深藏不露；章：同「彰」。深藏不露，却日渐彰明——本章的主旨。"},{id:"diran",term:"的然而日亡",pinyin:"dì rán ér rì wáng",meaning:"的然：鲜明显露。鲜明显露，却日渐消亡。"},{id:"danbuyan",term:"淡而不厌",pinyin:"dàn ér bù yàn",meaning:"平淡而不令人厌烦。"},{id:"jianwen",term:"简而文",pinyin:"jiǎn ér wén",meaning:"简约而有文采。"},{id:"wenli",term:"温而理",pinyin:"wēn ér lǐ",meaning:"温和而有条理。"},{id:"zhiyuan",term:"知远之近",pinyin:"zhī yuǎn zhī jìn",meaning:"知道远的由近处而来。"},{id:"zhifeng",term:"知风之自",pinyin:"zhī fēng zhī zì",meaning:"知道风从何处起（自：由来）。"},{id:"zhiwei",term:"知微之显",pinyin:"zhī wēi zhī xiǎn",meaning:"知道隐微的终将显明。"},{id:"rude",term:"入德",pinyin:"rù dé",meaning:"进入德之门。"},{id:"neixingbujiu",term:"内省不疚",pinyin:"nèi xǐng bù jiù",meaning:"自我省察而无愧。疚：病、愧。"},{id:"wuwuyuzhi",term:"无恶于志",pinyin:"wú wù yú zhì",meaning:"恶：读 wù，愧。于自己的心志无所愧恶。"},{id:"wulou",term:"屋漏",pinyin:"wū lòu",meaning:"室之西北隅（暗处）。朱注：「屋漏，室西北隅也。」不愧屋漏，即独处暗室亦无愧。"},{id:"fuyue",term:"鈇钺",pinyin:"fū yuè",meaning:"鈇：铡刀；钺：大斧。古代刑具。不怒而民威于鈇钺，谓不必发怒，民自畏服甚于刑威。"},{id:"buxianweide",term:"不显惟德",pinyin:"bù xiǎn wéi dé",meaning:"《诗·周颂·烈文》句。其德显明。"},{id:"xing",term:"刑",pinyin:"xíng",meaning:"同「型」，效法。百辟其刑之：诸侯都效法他。"},{id:"deyourumao",term:"德輶如毛",pinyin:"dé yóu rú máo",meaning:"輶：轻。德轻如毛——《诗·大雅·烝民》句。"},{id:"lun",term:"伦",pinyin:"lún",meaning:"比类、比拟。毛犹有伦，谓「如毛」尚可比拟。"},{id:"shangtianzhizai",term:"上天之载",pinyin:"shàng tiān zhī zài",meaning:"载：事、化育。上天的化育。《诗·大雅·文王》句。"},{id:"wushengwuxiu",term:"无声无臭",pinyin:"wú shēng wú xiù",meaning:"臭：读 xiù，气味。无声无气可闻——极言其至，全篇以此终。"}];return(p,n)=>{const g=t("DaoTextReading"),r=t("DaoKeywordCards");return h(),m("div",null,[n[0]||(n[0]=i("h1",{id:"中庸·第33章",tabindex:"-1"},[e("中庸·第33章 "),i("a",{class:"header-anchor",href:"#中庸·第33章","aria-label":'Permalink to "中庸·第33章"'},"​")],-1)),n[1]||(n[1]=i("h2",{id:"【原典层】原文",tabindex:"-1"},[e("【原典层】原文 "),i("a",{class:"header-anchor",href:"#【原典层】原文","aria-label":'Permalink to "【原典层】原文"'},"​")],-1)),n[2]||(n[2]=i("p",null,[e("末章引《诗》起句「"),i("strong",null,"衣锦尚絅"),e("」，说君子之道「"),i("strong",null,"闇然而日章"),e("」；中段连引《诗》句，逐层讲「人所不见」处的功夫；结尾以「"),i("strong",null,"上天之载，无声无臭"),e("」收束全篇。默认竹简沉浸通读；切「经典阅读」可点生词。")],-1)),a(g,{colophon:"衣锦尚絅 · 闇然而日章 · 无声无臭",tone:"ink",sections:s,glossary:o,"default-mode":"slips","aria-label":"中庸·第33章 原文"}),n[3]||(n[3]=i("h2",{id:"【原典层】注音与字词",tabindex:"-1"},[e("【原典层】注音与字词 "),i("a",{class:"header-anchor",href:"#【原典层】注音与字词","aria-label":'Permalink to "【原典层】注音与字词"'},"​")],-1)),a(r,{items:[{term:"衣锦尚絅",pinyin:["yì","jǐn","shàng","jiǒng"],meaning:"衣读 yì（穿），絅为罩衣。穿锦衣而外罩单衣——不欲文采外露。"},{term:"闇然而日章",pinyin:["àn","rán","ér","rì","zhāng"],meaning:"闇然（深藏不露）却日渐彰明。"},{term:"的然而日亡",pinyin:["dì","rán","ér","rì","wáng"],meaning:"的然（鲜明显露）却日渐消亡——本章的总纲。"},{term:"淡而不厌",pinyin:["dàn","ér","bù","yàn"],meaning:"平淡而不令人厌。"},{term:"简而文",pinyin:["jiǎn","ér","wén"],meaning:"简约而有文采。"},{term:"温而理",pinyin:["wēn","ér","lǐ"],meaning:"温和而有条理。三组都是「而」字相连的两端相济。"},{term:"知远之近",pinyin:["zhī","yuǎn","zhī","jìn"],meaning:"知道远的从近处来。"},{term:"知风之自",pinyin:["zhī","fēng","zhī","zì"],meaning:"知道风从何处起。"},{term:"知微之显",pinyin:["zhī","wēi","zhī","xiǎn"],meaning:"知道微的终将显。有此三知，可与入德。"}]}),a(r,{items:[{term:"内省不疚",pinyin:["nèi","xǐng","bù","jiù"],meaning:"自我省察而无愧。"},{term:"无恶于志",pinyin:["wú","wù","yú","zhì"],meaning:"恶：读 wù，愧。于心志无所愧恶。"},{term:"不愧屋漏",pinyin:["bù","kuì","wū","lòu"],meaning:"屋漏：室之西北隅（暗处）。独处暗室亦无愧。"},{term:"不动而敬",pinyin:["bù","dòng","ér","jìng"],meaning:"不待动作而人自敬。"},{term:"不言而信",pinyin:["bù","yán","ér","xìn"],meaning:"不待言语而人自信。"},{term:"不赏而民劝",pinyin:["bù","shǎng","ér","mín","quàn"],meaning:"不必赏赐而百姓自勉。"},{term:"不怒而民威于鈇钺",pinyin:["bù","nù","ér","mín","wēi"],meaning:"不必发怒而百姓畏服，甚于刑具（鈇钺）。"},{term:"声色之于以化民",pinyin:["shēng","sè","zhī","yú","yǐ","huà","mín"],meaning:"用声（言语）色（颜色）来感化人民。"},{term:"末也",pinyin:["mò","yě"],meaning:"是末事——孔子语。"},{term:"德輶如毛",pinyin:["dé","yóu","rú","máo"],meaning:"輶：轻。说德轻如毛。"},{term:"毛犹有伦",pinyin:["máo","yóu","yǒu","lún"],meaning:"伦：比类。说「如毛」，毕竟还有个可比的。"},{term:"上天之载",pinyin:["shàng","tiān","zhī","zài"],meaning:"载：事、化育。上天的化育。"},{term:"无声无臭",pinyin:["wú","shēng","wú","xiù"],meaning:"臭读 xiù（气味）。无声无气可闻——到了无可比拟处，故曰「至矣」。全篇以此终。"}]}),n[4]||(n[4]=u("",30))])}}});export{x as __pageData,b as default};
